#!/bin/bash
# reverse synthetic benchmark: data generated by GOK (lmGOKc kinetics) and by A=0 (lmA0c kinetics) at 50 C; each dataset fitted by IMTS, GOK and A=0 (common noise, no datum, cold start at 42 C)
cd "$(dirname "$0")/.."
# activate the conda environment first (see environment.yml)
export JAX_PLATFORMS=cpu OMP_NUM_THREADS=1 ERR=1 VHR_SCALE=100 K=24 NTRAP=24 N_FINE=24 NEUTRAL=1 MAAD=1 B_OVER_A=2 LOGD0_HI=4.4
IM=start_joint1_final.json; A0F=gcd_params_irra024_joint_maad_ERR_nN_vs100.json; GKF=gcd_params_irrgok24_joint_maad_ERR_nN_vs100.json
IMTS_MODEL=gok IMTS_PARAMS=$GKF python synth.py gen lm_lmGOKc.json 50 1 1 synthGOK_T50.pkl > log_synth_gen_gok.txt 2>&1
IMTS_MODEL=a0  IMTS_PARAMS=$A0F python synth.py gen lm_lmA0c.json 50 1 1 synthA0_T50.pkl > log_synth_gen_a0.txt 2>&1
export NEFF_PROF=6 LAMFIX=tl=11.6,maad=1,lab=3.5,itl=3.5,prof=1 TSTART=42
for G in GOK A0; do P=synth${G}_T50.pkl
  SYNTH_DATA=$P IMTS_MODEL=imts IMTS_PARAMS=$IM python lm_inv.py $IM $IM sy${G}_I 8 14 0 > log_sy${G}_I.txt 2>&1
  SYNTH_DATA=$P IMTS_MODEL=gok  IMTS_PARAMS=$GKF python lm_inv.py $GKF $GKF sy${G}_G 4 14 0 > log_sy${G}_G.txt 2>&1
  SYNTH_DATA=$P IMTS_MODEL=a0   IMTS_PARAMS=$A0F python lm_inv.py $A0F $A0F sy${G}_A 4 14 0 > log_sy${G}_A.txt 2>&1
done
touch SYNTH2_DONE.marker
